/bin/bash -lc "python3 - <<'PY'
import json, subprocess
from pathlib import Path
r=subprocess.run(['python3','/workspace/tools.py','resolve','run://r-001'],capture_output=True,text=True,check=True)
runtime=json.loads(r.stdout)
p=json.loads(Path('proposal.json').read_text())
def validate(value,schema,path='"'$'"'):
    types={'object':dict,'array':list,'string':str,'boolean':bool}
    if 'type' in schema:
        assert isinstance(value,types[schema['type']]), (path,'type',schema['type'])
    if 'enum' in schema:
        assert value in schema['enum'], (path,'enum')
    if 'const' in schema:
        assert value == schema['const'], (path,'const')
    if isinstance(value,str):
        assert len(value)>=schema.get('minLength',0), (path,'minLength')
    if isinstance(value,list):
        assert len(value)>=schema.get('minItems',0), (path,'minItems')
        for i,item in enumerate(value):
            validate(item,schema.get('items',{}),f'{path}[{i}]')
    if isinstance(value,dict):
        assert set(schema.get('required',[]))<=set(value), (path,'missing required keys')
        props=schema.get('properties',{})
        if schema.get('additionalProperties') is False:
            assert set(value)<=set(props), (path,'extra keys')
        for key,item in value.items():
            if key in props:
                validate(item,props[key],path+'.'+key)
validate(p['study'],runtime['study_schema'])
assert runtime['phase']=='propose'
assert p['parent_trial'] in runtime['context']['allowed_observation_ids']
assert p['study']['protocol_ref']==runtime['required_study_protocol_ref']
for ka in p['knowledge_assessments']:
    assert set(ka)=={'knowledge_id','decision','rationale','transformed_mechanism','variant_names','nearest_work_difference','falsifier'}
    assert ka['decision'] in {'used','considered','rejected','unresolved'}
    assert set(ka['variant_names'])<=set(v['name'] for v in p['variants'])
print('Full study schema validated recursively using the declared types, required keys, additionalProperties, enum, const, minLength and minItems.')
print('Proposal phase, parent lineage, protocol identity, evidence IDs and knowledge-assessment fields verified.')
print('Registered standalone files:',', '.join(v['file'] for v in p['variants']))
print('No training, package installation, withheld scoring, or host-owned source edits performed.')
PY"

